/* Lot 95: computed values of registered values (wf_cssprop_compute_ctx) (generated by scripts/lot95_propgen.py; expectations from lot95_propmodel.py). */
#include "../../framework/unity.h"
#include <string.h>
#include "wf_cssprop.h"

static wf_cssprop_t g_p;
static char g_o[128];

static const char *cv(const char *syn, const char *v, int ctx, int vw, int vh) {
    wf_cssprop_ctx_t c;
    int r;
    memset(&g_p, 0, sizeof(g_p));
    g_p.syntax = (unsigned char)wf_cssprop_syntax_parse(syn, (int)strlen(syn), &g_p);
    if (!g_p.syntax) return "BAD SYNTAX";
    c.vw = vw; c.vh = vh;
    r = wf_cssprop_compute_ctx(&g_p, v, ctx ? &c : 0, g_o, (int)sizeof(g_o));
    if (!r) return g_o[0] ? "KEEP BUT WRITTEN" : "KEEP";
    if (!strcmp(g_o, v)) return "SAME BUT 1";
    return g_o;
}

static void test_l95_compute_0(void) {
    TEST_ASSERT_EQUAL_STRING("KEEP", cv("'<length-percentage>+'", "calc(96cm * 284.5 + -90% * -45)", 1, 375, 812));
    TEST_ASSERT_EQUAL_STRING("KEEP", cv("'stretch | <string>'", "\"x\\\"y\"", 1, 1000, 1000));
    TEST_ASSERT_EQUAL_STRING("3693.276deg", cv("'small | <angle>#'", "calc(10.2591turn)", 1, 0, 0));
    TEST_ASSERT_EQUAL_STRING("KEEP", cv("'<custom-ident> | <transform-function>+'", "rotatex(calc(263deg + 12rad + 352.921turn))", 1, 1280, 720));
    TEST_ASSERT_EQUAL_STRING("KEEP", cv("'<percentage>'", "small", 0, 0, 0));
    TEST_ASSERT_EQUAL_STRING("skewy(-14495.832deg)", cv("'<transform-function> | <integer>'", "skewy( -253rad )", 0, 0, 0));
    TEST_ASSERT_EQUAL_STRING("KEEP", cv("'<time>#'", "3s", 1, 1280, 720));
    TEST_ASSERT_EQUAL_STRING("KEEP", cv("'<number>'", "96", 1, 640, 480));
    TEST_ASSERT_EQUAL_STRING("KEEP", cv("'<url>'", "url(e\\(f.png)", 1, 1000, 1000));
    TEST_ASSERT_EQUAL_STRING("8079.2898", cv("'<resolution> | <number>'", "calc(0 + (79 + 2) * 100.42570 + -55.19187)", 0, 0, 0));
}

